-- Backup of public.add_weekly_xp before 20261029 migration
pg_get_functiondef
CREATE OR REPLACE FUNCTION public.add_weekly_xp(delta integer) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ DECLARE caller_id UUID := auth.uid(); now_time TIMESTAMPTZ := timezone('utc'::text, now()); last_time TIMESTAMPTZ; target_week DATE; current_xp INT := 0; applied_delta INT := 0; BEGIN IF caller_id IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF; IF delta < 1 OR delta > 15 THEN RAISE EXCEPTION 'Invalid XP delta: must be between 1 and 15'; END IF; SELECT last_xp_at INTO last_time FROM players WHERE id = caller_id; IF last_time IS NOT NULL AND (now_time - last_time) < interval '2 seconds' THEN RAISE EXCEPTION 'Rate limited: please wait 2 seconds'; END IF; target_week := (date_trunc('week', now_time))::DATE; SELECT COALESCE(xp, 0) INTO current_xp FROM weekly_xp WHERE player_id = caller_id AND week_start = target_week; IF (current_xp + delta) > 5000 THEN applied_delta := GREATEST(0, 5000 - current_xp); ELSE applied_delta := delta; END IF; IF applied_delta > 0 THEN INSERT INTO weekly_xp(player_id, week_start, xp) VALUES (caller_id, target_week, current_xp + applied_delta) ON CONFLICT (player_id, week_start) DO UPDATE SET xp = weekly_xp.xp + applied_delta; END IF; UPDATE players SET last_xp_at = now_time WHERE id = caller_id; RETURN jsonb_build_object('success', true, 'delta', applied_delta, 'new_xp', current_xp + applied_delta); END; $function$